package com.yeyamo_mobile.api.culture_service.application;
import static com.yeyamo_mobile.api.culture_service.application.ChallengeDtos.*;import com.yeyamo.foundation.domain.*;import com.yeyamo_mobile.api.culture_service.domain.*;import com.yeyamo_mobile.api.culture_service.infrastructure.persistence.ChallengeRepositories.*;import java.time.Instant;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service@Transactional public class CultureChallengeService{private final Challenges challenges;private final Prompts prompts;private final Participants participants;private final Submissions submissions;private final Consents consents;private final CultureEventPublisher events;public CultureChallengeService(Challenges c,Prompts p,Participants pa,Submissions s,Consents co,CultureEventPublisher e){challenges=c;prompts=p;participants=pa;submissions=s;consents=co;events=e;}
 @Transactional(readOnly=true)public Page<ChallengeResponse> list(Pageable p){return challenges.findByStatus(CultureChallenge.Status.ACTIVE,p).map(c->ChallengeResponse.from(c,prompts.findByChallengeIdOrderByDisplayOrder(c.getId())));}@Transactional(readOnly=true)public ChallengeResponse get(UUID id){CultureChallenge c=require(id);return ChallengeResponse.from(c,prompts.findByChallengeIdOrderByDisplayOrder(id));}
 public ParticipationResponse join(UUID id,String actor){active(id);Optional<CultureChallengeParticipant>existing=participants.findByChallengeIdAndUserId(id,actor);if(existing.isPresent()){CultureChallengeParticipant participant=existing.get();return new ParticipationResponse(id,participant.getJoinedAt(),participant.getCompletedAt());}try{CultureChallengeParticipant participant=participants.save(CultureChallengeParticipant.join(id,actor));events.publish("CultureChallengeJoined",id,Map.of("challengeId",id,"userId",actor));return new ParticipationResponse(id,participant.getJoinedAt(),participant.getCompletedAt());}catch(DataIntegrityViolationException e){CultureChallengeParticipant participant=participants.findByChallengeIdAndUserId(id,actor).orElseThrow();return new ParticipationResponse(id,participant.getJoinedAt(),participant.getCompletedAt());}}
 public SubmissionResponse submit(UUID id,SubmissionRequest r,String actor){CultureChallenge c=active(id);CultureChallengeParticipant participant=participants.findByChallengeIdAndUserId(id,actor).orElseThrow(()->new CultureException("CHALLENGE_NOT_JOINED","Rejoignez le défi avant de participer",HttpStatus.CONFLICT));if(submissions.findByChallengeIdAndUserId(id,actor).isPresent())throw new CultureException("CHALLENGE_ALREADY_SUBMITTED","Une réponse existe déjà pour ce défi",HttpStatus.CONFLICT);if(c.getCountryCode()!=null&&r.languageCode()!=null)new LanguageReference(r.languageCode());if(c.getLanguageCode()!=null&&!c.getLanguageCode().equals(new LanguageReference(r.languageCode()).languageCode()))throw new CultureException("CHALLENGE_LANGUAGE_MISMATCH","Langue incompatible avec le défi",HttpStatus.BAD_REQUEST);if(r.recordsAnotherPerson()&&!r.consentConfirmed())throw new CultureException("CONSENT_REQUIRED","Le consentement de la personne enregistrée est obligatoire",HttpStatus.BAD_REQUEST);boolean moderated=c.isModerationRequired()||r.recordsAnotherPerson()||r.involvesMinor()||r.sacredCeremony()||r.personalData()||r.hateSpeechSuspected();String reason=moderated?moderationReason(r):null;CultureChallengeSubmission s=submissions.save(CultureChallengeSubmission.create(actor,id,r.postId(),r.cultureContributionId(),r.mediaIds(),r.languageCode(),r.translation(),moderated,reason));consents.save(CultureConsentDeclaration.declared(s.getId(),actor,r.recordsAnotherPerson(),r.consentConfirmed(),r.anonymized(),r.sourcePersonName()));Map<String,Object> payload=new LinkedHashMap<>();payload.put("challengeId",id);payload.put("submissionId",s.getId());payload.put("userId",actor);payload.put("moderationRequired",moderated);payload.put("moderationReason",reason);events.publish("CultureChallengeSubmitted",id,payload);if(c.getType()==CultureChallenge.Type.ORAL_HISTORY||c.getType()==CultureChallenge.Type.ASK_AN_ELDER||c.getType()==CultureChallenge.Type.FAMILY_STORY)events.publish("OralHistorySubmitted",id,payload);if(!moderated){participant.complete();events.publish("CultureChallengeCompleted",id,Map.of("challengeId",id,"userId",actor,"submissionId",s.getId(),"rewardDefinitionId",String.valueOf(c.getRewardDefinitionId())));}return SubmissionResponse.from(s);}
 @Transactional(readOnly=true)public Page<SubmissionResponse> accepted(UUID challenge,Pageable p){require(challenge);return submissions.findByChallengeIdAndStatus(challenge,CultureChallengeSubmission.Status.ACCEPTED,p).map(SubmissionResponse::from);}@Transactional(readOnly=true)public List<ParticipationResponse> mine(String actor){return participants.findByUserIdOrderByJoinedAtDesc(actor).stream().map(p->new ParticipationResponse(p.getChallengeId(),p.getJoinedAt(),p.getCompletedAt())).toList();}
 public void withdraw(UUID id,String actor){CultureChallengeSubmission s=submissions.findById(id).orElseThrow(()->new CultureException("SUBMISSION_NOT_FOUND","Soumission introuvable",HttpStatus.NOT_FOUND));try{s.withdraw(actor);}catch(SecurityException e){throw new CultureException("FORBIDDEN","Soumission inaccessible",HttpStatus.FORBIDDEN);}consents.save(CultureConsentDeclaration.withdrawn(id,actor));events.publish("CultureChallengeSubmissionWithdrawn",s.getChallengeId(),Map.of("challengeId",s.getChallengeId(),"submissionId",id,"userId",actor));}
 private CultureChallenge active(UUID id){CultureChallenge c=require(id);if(!c.available(Instant.now()))throw new CultureException("CHALLENGE_NOT_ACTIVE","Défi expiré ou indisponible",HttpStatus.CONFLICT);return c;}private CultureChallenge require(UUID id){return challenges.findById(id).orElseThrow(()->new CultureException("CHALLENGE_NOT_FOUND","Défi introuvable",HttpStatus.NOT_FOUND));}private String moderationReason(SubmissionRequest r){List<String>x=new ArrayList<>();if(r.recordsAnotherPerson())x.add("RECORDED_PERSON");if(r.involvesMinor())x.add("MINOR");if(r.sacredCeremony())x.add("SACRED");if(r.personalData())x.add("PERSONAL_DATA");if(r.hateSpeechSuspected())x.add("HATE_SPEECH");return x.isEmpty()?"CHALLENGE_POLICY":String.join(",",x);}}
